from ii_patchlib import *
p=Patches('clauses4')
p.gap(158,r"$f(a)=y'$ y $f(b)=y$.")
p.regex('7.1.4',r'Para obtener.*?(?=\\end\{proof\})',r"""Para realizar las condiciones $f(a)=y'$ y $f(b)=y$, así como la condición adicional (i) (resp. (ii)), se toma $Y'=\operatorname{Spec}(A')$, donde $A'$ es un anillo de valuación que domina a $\mathcal{O}_{y'}$ y que es completo y tiene un cuerpo residual algebraicamente cerrado, extensión de $\boldsymbol{k}(x)$ (resp. un anillo de valuación $A'$ que domina a $\mathcal{O}_{y'}$ y cuyo cuerpo de fracciones es $\boldsymbol{k}(x)$); la existencia de $A'$ está garantizada por (\hyperref[II.7.1.2-fr]{7.1.2}).
""",note='Translated the supplied French choice of valuation ring; removed the inherited alternative construction, without adding a mathematical correction.')
p.replace('7.1.5','dimensión~1','dimensión $1$')
p.replace('7.1.6',r'un anillo local noetheriano $A$ de dimensión~1',r'un anillo local $A$, noetheriano y de dimensión $1$')
p.replace('7.1.7','altura~1','rango $1$')
p.replace('7.1.7','dimensión~1','dimensión $1$',count=2)
p.replace('7.2.1',r"de $y=f(x)$, existe",r"de $y=f(x)$, distinta de $y$, existe")
p.gap(168,r'$g_1$, $g_2$')
p.replace('7.3.2',r'$A$ un anillo de valuación, $K$ su cuerpo de fracciones, $Y=\operatorname{Spec}(A)$',r'$A$ un anillo de valuación, $Y=\operatorname{Spec}(A)$')
p.replace('7.3.2',r'es igual a $K$;',r'es igual a $K$, cuerpo de fracciones de $A$;')
p.replace('7.3.2',r'los \emph{gérmenes}, en el punto $b$, de $Y$-secciones definidas en vecindades de $b$',r'los \emph{gérmenes} de $Y$-secciones (definidas en vecindades de $b$) en el punto $b$')
p.replace('7.3.9',r'donde $\zeta\in K^\times$ y los $c_i\in K$ no son todos nulos',r'de $K$, donde $\zeta\neq0$ y los $c_i$ son elementos no todos nulos de $K$')
p.replace('7.3.10',r'que domine a $\sh{O}_y$ y tenga a $L$ por cuerpo de fracciones',r'que tenga a $L$ por cuerpo de fracciones y domine a $\mathcal{O}_y$')
p.replace('7.3.10',r'que domina a $\sh{O}_z$ y tiene a $L$ por cuerpo de fracciones',r'que tiene a $L$ por cuerpo de fracciones y domina a $\mathcal{O}_z$')
p.replace('7.4.1',r'$1$','1',count=5);p.replace('7.4.1',r'$0$','0')
for u in ['7.4.2','7.4.4','7.4.6']:p.replace(u,r'$1$','1')
p.replace('7.4.9',r'un $k$-esquema algebraico \emph{propio}',r'un $k$-esquema algebraico \textup{propio} sobre $k$')
p.replace('7.4.10',r'para cada $i$ existen un entero',r'existen un entero')
for u in ['7.4.13','7.4.15']:p.replace(u,r'irreducible sobre $k$, con cuerpo de funciones $K=R(X)$',r'irreducible de cuerpo $R(X)=K$')
p.replace('7.4.13',r'\emph{completa} sobre $k$, con cuerpo de funciones $L=R(Y)$',r'\textup{completa} de cuerpo $L=R(Y)$')
p.replace('7.4.14',r'Entonces $Y$ es un esquema íntegro',r'Este es, en efecto, un esquema íntegro')
p.replace('7.4.15',r'Para que tal morfismo sea dominante',r'Para que $u$ sea dominante')
p.replace('7.4.18',r'una curva algebraica normal sobre $k$, de cuerpo de funciones $K$',r'una curva algebraica normal de cuerpo $K$')
p.replace('7.4.18',r'cuando $x$ es el punto genérico, o bien anillos de valuación discreta que contienen a $k$ y tienen a $K$ por cuerpo de fracciones, cuando $x$ es distinto del punto genérico',r'cuando $x$ es el punto genérico; si $x$ es distinto del punto genérico, $\mathcal{O}_x$ es un anillo de valuación discreta que contiene a $k$ y tiene a $K$ por cuerpo de fracciones')
p.save()
